import sys
import json
from typing import List

class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        diagonals = {}

        # Collect elements for each diagonal
        # A diagonal is identified by the difference k = row - col
        # k ranges from -(n-1) to (n-1)
        for r in range(n):
            for c in range(n):
                k = r - c
                if k not in diagonals:
                    diagonals[k] = []
                diagonals[k].append(grid[r][c])

        # Sort diagonals based on the rule
        # Bottom-left triangle (including main diagonal): k >= 0 -> non-increasing (descending)
        # Top-right triangle: k < 0 -> non-decreasing (ascending)
        for k in diagonals:
            if k >= 0:
                diagonals[k].sort(reverse=True)
            else:
                diagonals[k].sort()

        # Reconstruct the grid
        result = [[0] * n for _ in range(n)]
        # Track current index for each diagonal to place elements back in order
        # Since we collected elements in row-major order, the order in the list
        # corresponds to the order of cells in the diagonal (top-left to bottom-right).
        indices = {k: 0 for k in diagonals}

        for r in range(n):
            for c in range(n):
                k = r - c
                idx = indices[k]
                result[r][c] = diagonals[k][idx]
                indices[k] += 1

        return result

if __name__ == "__main__":
    # Read input from stdin
    # Using sys.stdin.read() to handle the input string which represents the matrix
    input_data = sys.stdin.read().strip()
    if input_data:
        try:
            grid = json.loads(input_data)
            sol = Solution()
            result = sol.sortMatrix(grid)
            print(json.dumps(result))
        except Exception:
            pass
