from typing import List

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        if n == 0:
            return 0

        # Precompute sets for each property to handle distinct integers
        sets = [set(p) for p in properties]

        # Union-Find (DSU) initialization
        parent = list(range(n))

        def find(i):
            root = i
            while parent[root] != root:
                root = parent[root]
            # Path compression
            curr = i
            while curr != root:
                next_node = parent[curr]
                parent[curr] = root
                curr = next_node
            return root

        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                parent[root_i] = root_j
                return True
            return False

        # Iterate over all pairs to build the graph
        for i in range(n):
            for j in range(i + 1, n):
                # Calculate intersection size
                common = len(sets[i] & sets[j])
                if common >= k:
                    union(i, j)

        # Count connected components
        roots = set()
        for i in range(n):
            roots.add(find(i))

        return len(roots)

if __name__ == "__main__":
