    if len(lines) >= 2:
        # Parse properties (first line) and k (second line)
        # Using eval to parse the list of lists
        properties = eval(lines[0])
        k = int(lines[1])

        solution = Solution()
        result = solution.numberOfComponents(properties, k)
        print(result)
