import sys
from typing import List

class Solution:
    def minArraySum(self, nums: List[int], k: int, op1: int, op2: int) -> int:
        n = len(nums)
        # dp[j][l] stores the maximum reduction (gain) achievable using exactly j Op1s and l Op2s
        # Initialize with -1 to represent unreachable states
        dp = [[-1] * (op2 + 1) for _ in range(op1 + 1)]
        dp[0][0] = 0

        for x in nums:
            # Iterate backwards to allow in-place updates
            # We want to update dp[j][l] based on values from the previous element iteration
            # Since we iterate downwards, dp[j-1][l], dp[j][l-1], dp[j-1][l-1] are from the previous iteration
            for j in range(op1, -1, -1):
                for l in range(op2, -1, -1):
                    if dp[j][l] == -1:
                        continue

                    current_gain = dp[j][l]

                    # Option 1: Apply Operation 1
                    # Cost: 1 Op1
                    if j + 1 <= op1:
                        gain1 = x - (x + 1) // 2
                        if current_gain + gain1 > dp[j+1][l]:
                            dp[j+1][l] = current_gain + gain1

                    # Option 2: Apply Operation 2
                    # Cost: 1 Op2
                    if l + 1 <= op2 and x >= k:
                        gain2 = k
                        if current_gain + gain2 > dp[j][l+1]:
                            dp[j][l+1] = current_gain + gain2

                    # Option 3: Apply Both Operations
                    # Cost: 1 Op1, 1 Op2
                    if j + 1 <= op1 and l + 1 <= op2:
                        # Determine the best order and validity
                        # Op1 then Op2: x -> ceil(x/2) -> ceil(x/2) - k
                        # Valid if ceil(x/2) >= k
                        val_after_op1 = (x + 1) // 2
                        if val_after_op1 >= k:
                            gain_both = x - (val_after_op1 - k)
                        # Op2 then Op1: x -> x - k -> ceil((x-k)/2)
                        # Valid if x >= k
                        elif x >= k:
                            val_after_op2 = x - k
                            gain_both = x - (val_after_op2 + 1) // 2
                        else:
                            gain_both = -1

                        if gain_both != -1:
                            if current_gain + gain_both > dp[j+1][l+1]:
                                dp[j+1][l+1] = current_gain + gain_both

        # Find the maximum gain possible with at most op1 Op1s and op2 Op2s
        max_gain = 0
        for j in range(op1 + 1):
            for l in range(op2 + 1):
                if dp[j][l] > max_gain:
                    max_gain = dp[j][l]

        return sum(nums) - max_gain

if __name__ == "__main__":
    # Reading input from stdin
    try:
        # Read nums
        line1 = sys.stdin.readline()
        if line1:
            # Parse nums list
            nums = eval(line1.strip())

            k = int(sys.stdin.readline().strip())
            op1 = int(sys.stdin.readline().strip())
            op2 = int(sys.stdin.readline().strip())

            solution = Solution()
            result = solution.minArraySum(nums, k, op1, op2)
            print(result)
    except Exception:
        pass
