from typing import List
import ast

class Solution:
    def buttonWithLongestTime(self, events: List[List[int]]) -> int:
        if not events:
            return -1

        max_time = -1
        result_index = -1
        prev_time = 0

        for index, time in events:
            current_time = time - prev_time

            if current_time > max_time:
                max_time = current_time
                result_index = index
            elif current_time == max_time:
                if index < result_index:
                    result_index = index

            prev_time = time

        return result_index

if __name__ == "__main__":
    input_lines = []
    try:
        while True:
            line = input()
            input_lines.append(line)
    except EOFError:
        pass

    if input_lines:
        input_data = " ".join(input_lines)
        try:
            events = ast.literal_eval(input_data)
            sol = Solution()
            print(sol.buttonWithLongestTime(events))
