class Solution:
    def minimumOperations(self, nums: List[int]) -> int:
        n = len(nums)
        k = 0
        while True:
            # After k operations, we have removed 3*k elements from the beginning.
            # The remaining array is nums[3*k:].
            # If 3*k >= n, the array is empty, which is considered distinct.
            if 3 * k >= n:
                return k

            # Check if the remaining elements are distinct
            remaining = nums[3 * k:]
            if len(set(remaining)) == len(remaining):
                return k

            k += 1

